# ---------------------------------------------------------------------------
# LOCAL IMAGE LOADER
# ---------------------------------------------------------------------------
# The Streamlit component runs inside an iframe, so a normal relative URL
# such as "db/images/B/ball.webp" is not reliable there.  We therefore read
# the local WEBP/PNG/JPG file in Python and convert it to a data URI before
# sending it to the browser.
#
# Supported naming:
#   db/images/B/ball.webp
#   db/images/B/B_ball.webp
#   db/images/B/ball.png
#   db/images/B/B_ball.png
# and similarly for every A-Z folder.
# ---------------------------------------------------------------------------
def _image_candidates(letter, word):
    letter = str(letter).upper()
    clean = re.sub(r"[^a-z0-9]+", "_", str(word).strip().lower()).strip("_")
    original = str(word).strip().lower()

    names = []
    for base in (clean, original):
        if base and base not in names:
            names.append(base)

    extensions = (".webp", ".png", ".jpg", ".jpeg")
    roots = [
        Path("db") / "images" / letter,
        Path("db") / "images" / letter.lower(),
    ]

    candidates = []
    for root in roots:
        for name in names:
            for prefix in ("", f"{letter}_", f"{letter.lower()}_"):
                for ext in extensions:
                    candidates.append(root / f"{prefix}{name}{ext}")
    return candidates


def _local_image_data_uri(letter, word):
    for path in _image_candidates(letter, word):
        if path.is_file():
            mime = mimetypes.guess_type(path.name)[0] or "image/webp"
            try:
                encoded = base64.b64encode(path.read_bytes()).decode("ascii")
                return f"data:{mime};base64,{encoded}"
            except OSError:
                pass
    return None


def _use_local_images():
    """Replace embedded prototype images with files from db/images when found."""
    for letter, items in DATA.get("words", {}).items():
        for item in items:
            local_src = _local_image_data_uri(letter, item.get("word", ""))
            if local_src:
                item["src"] = local_src


_use_local_images()


